mapper.select:
SELECT R.REVIEW_SEQ , R.USER_SEQ , R.USER_NAME , R.PRODUCT_SEQ , R.RATING , R.CONTENT , R.REG_DATE , R.UPD_DATE , P.NAME AS PRODUCT_NAME FROM TB_REVIEW R INNER JOIN TB_PRODUCT P ON R.PRODUCT_SEQ = P.PRODUCT_SEQ WHERE R.PRODUCT_SEQ = #{productSeq} ORDER BY R.REG_DATE DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM TB_REVIEW
WHERE PRODUCT_SEQ = #{productSeq}

mapper.insert:
INSERT INTO TB_REVIEW ( PRODUCT_SEQ
    , USER_SEQ
    , USER_NAME
    , RATING
    , CONTENT
    , REG_DATE)
VALUES ( #{productSeq}
    , #{userSeq}
    , #{userName}
    , #{rating}
    , #{content}
    , NOW())

mapper.update:
UPDATE TB_REVIEW
SET RATING = #{rating}
    , CONTENT = #{content}
    , UPD_DATE = NOW()
WHERE REVIEW_SEQ = #{reviewSeq}
    AND USER_NAME = #{userName}

mapper.delete:
DELETE
FROM TB_REVIEW
WHERE REVIEW_SEQ = #{reviewSeq}
    AND USER_NAME = #{userName}
